require "download_strategy"

# Download a release asset from a PRIVATE GitHub repo. The plain
# github.com/.../releases/download/... URL 404s for private repos (it
# needs a web session, not a token), so resolve the asset id via the
# API and pull the api.github.com/.../releases/assets/<id> endpoint
# with Accept: octet-stream + HOMEBREW_GITHUB_API_TOKEN. The built-in
# strategy of this name was removed from Homebrew, so it is vendored.
class GitHubPrivateRepositoryReleaseDownloadStrategy < CurlDownloadStrategy
  require "utils/github"

  def initialize(url, name, version, **meta)
    super
    parse_url_pattern
    set_github_token
  end

  def parse_url_pattern
    url_pattern = %r{https://github.com/([^/]+)/([^/]+)/releases/download/([^/]+)/(\S+)}
    match = @url.match(url_pattern)
    raise CurlDownloadStrategyError, "Invalid URL pattern for GitHub Release: #{@url}" if match.nil?

    _, @owner, @repo, @tag, @filename = *match
  end

  def download_url
    "https://api.github.com/repos/#{@owner}/#{@repo}/releases/assets/#{asset_id}"
  end

  private

  def _fetch(url:, resolved_url:, timeout:)
    curl_download(
      download_url,
      "--header", "Accept: application/octet-stream",
      "--header", "Authorization: token #{@github_token}",
      to:          temporary_path,
      try_partial: @try_partial,
      timeout:     timeout
    )
  end

  def set_github_token
    @github_token = ENV.fetch("HOMEBREW_GITHUB_API_TOKEN", nil)
    return if @github_token.present?

    raise CurlDownloadStrategyError, "HOMEBREW_GITHUB_API_TOKEN is required for #{@owner}/#{@repo}."
  end

  def asset_id
    @asset_id ||= begin
      metadata = GitHub::API.open_rest("https://api.github.com/repos/#{@owner}/#{@repo}/releases/tags/#{@tag}")
      asset = metadata.fetch("assets", []).find { |a| a["name"] == @filename }
      raise CurlDownloadStrategyError, "Asset #{@filename} not found in #{@owner}/#{@repo}@#{@tag}." if asset.nil?

      asset.fetch("id")
    end
  end
end

class Pbrainctl < Formula
  desc "MCP server + daemon for durable, validated long-term memory (phantom-brain)"
  homepage "https://github.com/neverprepared/phantom-brain"
  version "3.31.0"
  license "MIT"

  # Use `if Hardware::CPU.arm?` (not `on_arm`/`on_intel`): nested
  # on-arch blocks don't register url/sha256 at spec resolution,
  # so brew reports "formula requires at least a URL". This is the
  # GoReleaser-proven pattern (see mcp-slack.rb in the tap).
  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/neverprepared/phantom-brain/releases/download/v3.31.0/pbrainctl_darwin_arm64.tar.gz", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "0f2b7d52a1a73eaaaa6684eb9f78bb6c9a525edae2b51b0ae4be01862bf0f601"
    end
  end

  on_linux do
    if Hardware::CPU.intel?
      url "https://github.com/neverprepared/phantom-brain/releases/download/v3.31.0/pbrainctl_linux_amd64.tar.gz", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "c0fdd10d92ae8014cc87c77dddb8d06c162c32167c4cc8413e5532400cbb1a13"
    end
    if Hardware::CPU.arm?
      url "https://github.com/neverprepared/phantom-brain/releases/download/v3.31.0/pbrainctl_linux_arm64.tar.gz", using: GitHubPrivateRepositoryReleaseDownloadStrategy
      sha256 "1b664941be7f0e1d91bbc9f459f6621ee87778d418bc147eff5f3881c819e19d"
    end
  end

  def install
    bin.install "pbrainctl"
  end

  def caveats
    <<~CAVEAT
      pbrainctl is two roles in one binary — agent (`pbrainctl client mcp`)
      and daemon (`pbrainctl server serve`). For the agent, point your
      MCP host at it via .claude.json (or equivalent). For the daemon, set:

        PHANTOM_BRAIN_CONFIG_DIR  (default: ~/.config/phantom-brain-server)
        PHANTOM_BRAIN_DATA_DIR    (default: ~/.local/share/phantom-brain-server)

      then `pbrainctl server serve`. See:
        https://github.com/neverprepared/phantom-brain#setup
    CAVEAT
  end

  test do
    system "#{bin}/pbrainctl", "client", "version"
  end
